import{_ as a,o as e,c as i,a3 as t}from"./chunks/framework.Ctn2UYXF.js";const k=JSON.parse('{"title":"P1 · Store 与符号链接算法","description":"","frontmatter":{},"headers":[],"relativePath":"principles/01-virtual-store.md","filePath":"principles/01-virtual-store.md","lastUpdated":1792494191000}'),n={name:"principles/01-virtual-store.md"};function p(l,s,o,d,h,r){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="p1-·-store-与符号链接算法" tabindex="-1">P1 · Store 与符号链接算法 <a class="header-anchor" href="#p1-·-store-与符号链接算法" aria-label="Permalink to &quot;P1 · Store 与符号链接算法&quot;">​</a></h1><blockquote><p><strong>前置</strong>：读完成入门篇 + <a href="/pnpm-monorepo-tutorial-pages/04-dependency-sharing">04 依赖共享</a>　|　<strong>配套练习</strong>：<a href="/pnpm-monorepo-tutorial-pages/practice/03-phantom-dependency">E3 幻影依赖检测</a></p></blockquote><p>「pnpm 省磁盘」这句话人人会说，但<strong>省在哪一层、硬链接挂在哪、软链接指向谁</strong>，多数人答不上来。这一章用你本机真实目录把这套「双层注入」算法拆开。</p><h2 id="你将学到" tabindex="-1">你将学到 <a class="header-anchor" href="#你将学到" aria-label="Permalink to &quot;你将学到&quot;">​</a></h2><ul><li>全局 Store 的内容寻址（CAS）结构与硬链接导入方式</li><li><code>node_modules/.pnpm</code> 虚拟存储的目录命名规则与内部结构</li><li>项目 <code>node_modules</code> 里的软链接究竟指向哪里</li><li>为什么这套结构能「从物理上」杜绝幻影依赖</li></ul><h2 id="一、三层结构总览" tabindex="-1">一、三层结构总览 <a class="header-anchor" href="#一、三层结构总览" aria-label="Permalink to &quot;一、三层结构总览&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 全局 Store（跨项目共享，真正存文件的地方）</span></span>
<span class="line"><span>   ~/Library/pnpm/store/v11/files/&lt;2位分片&gt;/&lt;128位十六进制&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 虚拟存储（每个项目一份「包实例目录」的登记表）</span></span>
<span class="line"><span>   项目/node_modules/.pnpm/&lt;name&gt;@&lt;version&gt;_&lt;peer后缀&gt;/node_modules/&lt;name&gt;</span></span>
<span class="line"><span>        └─ 其中文件是 ① 的【硬链接】</span></span>
<span class="line"><span>        └─ 其依赖是同级 .pnpm 条目的【软链接】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 项目 / 各子包的 node_modules（你 require 时真正看的层）</span></span>
<span class="line"><span>   node_modules/&lt;name&gt;            → 软链接到 ②</span></span>
<span class="line"><span>   packages/ui/node_modules/react → 软链接到 ②</span></span>
<span class="line"><span>   packages/ui/node_modules/@tutorial/types → 软链接到源码目录（workspace 包）</span></span></code></pre></div><p>一句话概括：<strong>文件只存 ①，② 负责「哪些包、哪些版本、配哪套 peer」，③ 只放软链接做「谁能看见谁」的访问控制。</strong></p><h2 id="二、全局-store-内容寻址-cas" tabindex="-1">二、全局 Store：内容寻址（CAS） <a class="header-anchor" href="#二、全局-store-内容寻址-cas" aria-label="Permalink to &quot;二、全局 Store：内容寻址（CAS）&quot;">​</a></h2><p>先看看你机器上的真实 store：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> store</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># /Users/&lt;you&gt;/Library/pnpm/store/v11      ← macOS 实际路径（注意不是 .npmrc 里写的路径）</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> store path)&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># .pnpm-needs-build-marker  .tmp  files  index.db  links  projects</span></span></code></pre></div><p>关键在于 <code>files/</code>：<strong>按内容哈希存放</strong>，而不是按包名。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> store path)/files&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -5</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 00  01  02  03  04 ...                    ← 前两位十六进制做分片，防止单目录文件过多</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> store path)/files/00&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -3</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 00a250f585bdd6f18c19a983c0afd8ceddced0f7c86b36ca0d8306209557db65fc1ac7e3d9d0b921c4ec1c1690e37a66c3ba728593920c7eb78c6e8260db03</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ...</span></span></code></pre></div><p>文件名是 <strong>SHA-512 的十六进制</strong>（128 个字符）——这就是「内容寻址」：<strong>内容相同的文件在 store 里只存在一份</strong>，无论被多少项目、多少个包引用。这是「省磁盘」的第一半。</p><ul><li><code>files/</code>：CAS 文件本体；</li><li><code>index.db</code>：store 的索引（记录文件被哪些包引用、校验和等）；</li><li><code>links/</code>、<code>projects/</code>：按项目记录链接关系，<code>pnpm store prune</code> 据此判断「哪些文件已无人引用」从而安全删除。</li></ul><p><strong>第二半省磁盘</strong>来自导入方式：从 store 到虚拟存储<strong>默认用硬链接</strong>（同一份文件、多个路径，不复制数据）。若文件系统不支持硬链接，pnpm 会退化为复制，可用配置干预：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package-import-method</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # auto | hardlink | copy | clone</span></span></code></pre></div><blockquote><p>💡 <strong>硬链接的本质</strong>：两个路径指向<strong>同一个 inode</strong>。删掉其中一个路径，数据仍在（只要还有另一个链接）。这就是为什么 <code>node_modules</code> 删了不心疼——数据在 store 里。</p></blockquote><h2 id="三、虚拟存储-node-modules-pnpm" tabindex="-1">三、虚拟存储：<code>node_modules/.pnpm</code> <a class="header-anchor" href="#三、虚拟存储-node-modules-pnpm" aria-label="Permalink to &quot;三、虚拟存储：\`node_modules/.pnpm\`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node_modules/.pnpm</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -6</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># @algolia+abtesting@1.26.0</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># @algolia+autocomplete-core@1.17.7_@algolia+client-search@5.60.0_algoliasearch@5.60.0_search-insights@2.17.3</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ...</span></span></code></pre></div><p>命名规则：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;scope/name 中的 / 换成 +&gt;@&lt;version&gt;_&lt;peerA&gt;@&lt;ver&gt;_&lt;peerB&gt;@&lt;ver&gt;...</span></span></code></pre></div><ul><li>无 peer 依赖时：<code>clsx@2.1.1</code>；</li><li>有 peer 依赖时：把 peer 名与版本拼在后缀里，<strong>同版本包的不同 peer 组合 = 不同目录</strong>，从而各自拥有一份独立的依赖连线而不互相污染；</li><li>peer 后缀过长时，pnpm 会截断并追加一段哈希（上面第二条的 <code>..._search-insights@2.17.3</code>、以及更长的 <code>..._rw7bhhuygnl3qme6yt7cuf2hnq</code> 形式），避免文件名超出文件系统上限。</li></ul><p>再看一个条目内部：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node_modules/.pnpm/clsx@2.1.1/node_modules/</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># clsx                          ← 包本体（文件为 store 的硬链接）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node_modules/.pnpm/react-dom@18.3.1_react@18.3.1/node_modules/</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># loose-envify  react  react-dom  scheduler</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># └─ 包本体 + 它的全部直接依赖（皆为指向各自 .pnpm 条目的软链接）</span></span></code></pre></div><p><strong>规律</strong>：<code>.pnpm/&lt;pkg&gt;/node_modules/</code> 里放着「该包本体 + 它声明过的直接依赖」。因此 <strong>一个包运行时能 require 到什么，完全由它自己声明了什么决定</strong>——这就是幻影依赖被物理杜绝的原因。</p><h2 id="四、项目-node-modules-软链接" tabindex="-1">四、项目 <code>node_modules</code>：软链接 <a class="header-anchor" href="#四、项目-node-modules-软链接" aria-label="Permalink to &quot;四、项目 \`node_modules\`：软链接&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -la</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/ui/node_modules/</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># clsx        -&gt; ../../../node_modules/.pnpm/clsx@2.1.1/node_modules/clsx</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># react       -&gt; ../../../node_modules/.pnpm/react@18.3.1/node_modules/react</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># react-dom   -&gt; ../../../node_modules/.pnpm/react-dom@18.3.1_react@18.3.1/node_modules/react-dom</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># @tutorial/types -&gt; ../../../types</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># @tutorial/utils -&gt; ../../../utils</span></span></code></pre></div><p>两类链接值得区分：</p><table tabindex="0"><thead><tr><th>类型</th><th>指向</th><th>说明</th></tr></thead><tbody><tr><td>第三方包</td><td><code>node_modules/.pnpm/&lt;pkg&gt;@&lt;ver&gt;/node_modules/&lt;pkg&gt;</code></td><td><strong>软链接</strong>，最终数据来自 store 硬链接</td></tr><tr><td>workspace 包</td><td>源码目录（如 <code>packages/types</code>）</td><td>软链接直指源码，<strong>改动即生效</strong>，这也是「本地开发零成本」的实现基础</td></tr></tbody></table><blockquote><p>⚠️ 注意：workspace 包<strong>不经过 store</strong>。所以你在 <code>packages/ui</code> 里改一行代码，<code>apps/web</code> 立刻看到——因为它链接的就是源码目录本身，并非某个已构建产物。（这也解释了为什么包需要自己 <code>build</code> 才能产出 <code>dist</code>。）</p></blockquote><p><code>.bin/</code> 目录里则是 CLI 可执行文件的 shim，同样通过软链接/垫片脚本指向 <code>.pnpm</code> 中对应包的 bin。</p><h2 id="五、可调项与排障" tabindex="-1">五、可调项与排障 <a class="header-anchor" href="#五、可调项与排障" aria-label="Permalink to &quot;五、可调项与排障&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>作用</th><th>风险</th></tr></thead><tbody><tr><td><code>store-dir</code></td><td>全局 store 位置</td><td>放在慢盘上会拖慢所有项目</td></tr><tr><td><code>virtual-store-dir</code></td><td><code>node_modules/.pnpm</code> 的位置（默认即 <code>node_modules/.pnpm</code>）</td><td>一般不要改</td></tr><tr><td><code>package-import-method</code></td><td>硬链接 / 复制 / clone</td><td><code>copy</code> 会失去省磁盘特性，但可跨文件系统使用</td></tr></tbody></table><p><strong>实测踩坑（本仓库真实存在）</strong>：<code>.npmrc</code> 里写了 <code>store-dir=~/.pnpm-store</code>，但 <code>pnpm store path</code> 返回的是 <code>~/Library/pnpm/store/v11</code>——<strong><code>~</code> 并未按预期展开，配置实际未生效</strong>。</p><blockquote><p>✅ <strong>原则：永远用 <code>pnpm store path</code> 确认实际路径，不要假设配置文件里的路径一定生效。</strong></p></blockquote><p>常用排障命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> store</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 实际 store 位置</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> store</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 校验 store 完整性</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> store</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prune</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 清理无引用的文件（释放空间）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">du</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> store path)&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # store 占用</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">du</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node_modules</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # 项目占用（对比可见省了多少）</span></span></code></pre></div><h2 id="检查清单" tabindex="-1">检查清单 <a class="header-anchor" href="#检查清单" aria-label="Permalink to &quot;检查清单&quot;">​</a></h2><ul><li>[ ] 能画出 store → <code>.pnpm</code> → <code>node_modules</code> 三层流向</li><li>[ ] 能解释 <code>.pnpm</code> 目录名里的 <code>_peer@version</code> 后缀为何存在</li><li>[ ] 能用 <code>ls -la</code> 分辨「第三方包软链接」与「workspace 源码软链接」</li><li>[ ] 知道用 <code>pnpm store path</code> 而非 <code>.npmrc</code> 来确认真实 store 位置</li><li>[ ] 亲手实现幻影依赖检测：<a href="/pnpm-monorepo-tutorial-pages/practice/03-phantom-dependency">练习 E3</a></li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/pnpm-monorepo-tutorial-pages/principles/02-lockfile">P2 · lockfile 语义</a>：这套结构是如何被记录下来的</li></ul>`,43)])])}const g=a(n,[["render",p]]);export{k as __pageData,g as default};
